import { memo, useDeferredValue, useState, useTransition } from "react";

const SlowList = memo(function SlowList({ text }) {
  const items = [];
  for (let i = 0; i < 300; i++) {
    const start = performance.now();
    while (performance.now() - start < 1) {}     // simulate 1ms of work per row
    items.push(<li key={i}>{text} #{i}</li>);
  }
  return <ul>{items}</ul>;
});

export default function App() {
  const [text, setText] = useState("");
  const deferredText = useDeferredValue(text);
  const [tab, setTab] = useState("about");
  const [isPending, startTransition] = useTransition();

  return (
    <>
      <input value={text} onChange={e => setText(e.target.value)} />  {/* stays responsive */}
      <div style={{ opacity: text !== deferredText ? 0.5 : 1 }}>
        <SlowList text={deferredText} />
      </div>
      <button onClick={() => startTransition(() => setTab("posts"))}>
        Posts {isPending && "(loading...)"}
      </button>
      <p>Tab: {tab}</p>
    </>
  );
}

import { Component, Suspense, use } from "react";

class ErrorBoundary extends Component {
  state = { error: null };

  static getDerivedStateFromError(error) {
    return { error };                     // render fallback next
  }
  componentDidCatch(error, info) {
    console.error("Caught:", error, info.componentStack);   // report to monitoring
  }
  render() {
    if (this.state.error) {
      return (
        <div role="alert">
          <p>Couldn't load this section.</p>
          <button onClick={() => this.setState({ error: null })}>Try again</button>
        </div>
      );
    }
    return this.props.children;
  }
}

const failing = Promise.reject(new Error("503 from API"));
function Comments() {
  const comments = use(failing);          // rejection is thrown to the boundary
  return <ul>{comments.map(c => <li key={c.id}>{c.text}</li>)}</ul>;
}

export default function Post() {
  return (
    <ErrorBoundary>
      <Suspense fallback={<p>Loading comments...</p>}>
        <Comments />
      </Suspense>
    </ErrorBoundary>
  );
}

concepts.body:
An **Action** is an async function run inside a transition. React tracks its pending state, and updates made by it are batched and applied when it finishes. You get Actions in several ways.

**Form actions.** Pass a function to `<form action={fn}>` (or `<button formAction={fn}>`). React calls it with the form's `FormData` on submit, without a page reload, and resets uncontrolled fields when it succeeds.

**`useActionState(action, initialState)`** returns `[state, formAction, isPending]`. Your action receives `(previousState, formData)` and returns the next state, typically a result or error message:

```jsx
const [error, submit, isPending] = useActionState(async (prev, formData) => {
  const res = await updateName(formData.get("name"));
  return res.error ?? null;
}, null);
<form action={submit}>...</form>
```

Submissions are queued in order, and the state is the last returned value.

**`useFormStatus()`** (from `react-dom`) lets a component *inside* a form read `{ pending, data, method, action }` of the enclosing form's submission. It's perfect for a reusable `<SubmitButton>` that disables itself, with no prop drilling. It must be called in a child of the `<form>`, not the component that renders it.

**`useOptimistic(state, updateFn)`** shows a temporary value while an Action runs, like a sent message appearing immediately. When the Action finishes, the optimistic value is discarded and the real state is shown; if it failed, the UI simply reverts.

You can also start an Action from any handler with `startTransition(async () => {...})`. Validate input in the action, return errors as state rather than throwing for expected failures, and remember that with a framework the action can be a Server Function, so the same form works before JavaScript loads.

concepts.code:
import { useActionState, useOptimistic } from "react";
import { useFormStatus } from "react-dom";

async function saveTodo(text) {
  await new Promise(r => setTimeout(r, 800));
  if (text.length < 3) throw new Error("Too short");
  return { id: crypto.randomUUID(), text };
}

function SubmitButton() {
  const { pending } = useFormStatus();          // reads the parent <form>
  return <button disabled={pending}>{pending ? "Saving..." : "Add"}</button>;
}

export default function Todos() {
  const [state, formAction] = useActionState(async (prev, formData) => {
    const text = formData.get("text");
    addOptimistic(text);
    try {
      return { todos: [...prev.todos, await saveTodo(text)], error: null };
    } catch (e) {
      return { ...prev, error: e.message };
    }
  }, { todos: [], error: null });

  const [optimisticTodos, addOptimistic] = useOptimistic(
    state.todos,
    (todos, text) => [...todos, { id: "pending", text: text + " (saving)" }]
  );

  return (
    <form action={formAction}>
      <input name="text" />
      <SubmitButton />
      {state.error && <p role="alert">{state.error}</p>}
      <ul>{optimisticTodos.map(t => <li key={t.id}>{t.text}</li>)}</ul>
    </form>
  );
}

