    setUrgent(e.target.value);                     // sync lane: never interrupted
    startTransition(() => setSlow(e.target.value)); // transition lane: may restart
  }

  return (
    <>
      <input value={urgent} onChange={onChange} />
      <Child value={slow} />
    </>
  );
}
